onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl36_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("51-2")		    if dialog.show("Level36-1", faceWunai) ==1 then break end			if dialog.show("Level36-2", faceWunai) ==1 then break end			if dialog.show("Level36-3", faceBujie) ==1 then break end			sound.play("52-1")			if dialog.show("Level36-4", faceRenzhen) ==1 then break end			global.setBool("lvl36_b1")		until true		dialog.setSkipEnabled(false)    game.success()end